DROP TABLE IF EXISTS `sensorDataReport`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `sensorDataReport` (
  `IDSensorDataReport` int(11) NOT NULL AUTO_INCREMENT,
  `deviceID` int(11) DEFAULT NULL,
  `ReportName` varchar(128) DEFAULT NULL,
  `DateGenerated` datetime DEFAULT current_timestamp(),
  `sensorData` longtext DEFAULT NULL,
  PRIMARY KEY (`IDSensorDataReport`),
  KEY `fk_sensorDataReport_device_idx` (`deviceID`),
  CONSTRAINT `fk_sensorDataReport_device` FOREIGN KEY (`deviceID`) REFERENCES `device` (`IDDevice`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE=InnoDB AUTO_INCREMENT=62 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci COMMENT='Bilo bi dobro praznit sensorData tablicu i jednom mjesecno predgenerirat podatke za sve uredjaje, mjesecno, godisnje.\\nhttps://stackoverflow.com/questions/33926532/get-uncommitted-data-in-mysql\\nSELECT * FROM TABLE_NAME WITH (nolock), da read ne radi lock nad tablicom za insert--ovako--SELECT JSON_ARRAYAGG(JSON_OBJECT(''firstname'', firstname, ''lastname'', lastname)) from agrumy.person;';
