CREATE DEFINER=`agrumy`@`%` PROCEDURE `DeviceConfigControllerUpdate`(
	idDevice int,
	idDeviceConfigController int,
	tempLow int,
    tempHigh int,
    humidLow int,
    humidHigh int,
    moistLow int,
    moistHigh int,
    lightLow int,
    lightHigh int,
    waterLow int,
