    heatingInterval int,
    heatingIntervalLenght int,
    waterPumpIntervalEnabled int,
    waterPumpInterval int,
    waterPumpIntervalLenght int,
    relayEnabled bool,
    relay1 int,
    relay2 int,
    relay3 int,
    relay4 int,
    relay5 int,
    relay6 int,
    relay7 int,
    relay8 int
)
BEGIN
UPDATE deviceConfigController
SET 
    deviceConfigController.TempLow =  tempLow,
    deviceConfigController.TempHigh =  tempHigh,
    deviceConfigController.HumidLow =  humidLow,
    deviceConfigController.HumidHigh =  humidHigh,
	deviceConfigController.MoistLow =  moistLow,
    deviceConfigController.MoistHigh =  moistHigh,
    deviceConfigController.LightLow =  lightLow,
    deviceConfigController.LightHigh =  lightHigh,
    deviceConfigController.WaterLow =  waterLow,
    deviceConfigController.WaterHigh =  waterHigh,

	deviceConfigController.VentilationIntervalEnabled =  ventilationIntervalEnabled,
    deviceConfigController.VentilationInterval =  ventilationInterval,
    deviceConfigController.VentilationIntervalLenght =  ventilationIntervalLenght,
    deviceConfigController.LightIntervalEnabled =  lightIntervalEnabled,
    deviceConfigController.LightInterval =  lightInterval,
    deviceConfigController.LightIntervalLenght =  lightIntervalLenght,
    deviceConfigController.HeatingIntervalEnabled =  heatingIntervalEnabled,
    deviceConfigController.HeatingInterval =  heatingInterval,
    deviceConfigController.HeatingIntervalLenght =  heatingIntervalLenght,
    deviceConfigController.WaterPumpIntervalEnabled =  waterPumpIntervalEnabled,
    deviceConfigController.WaterPumpInterval =  waterPumpInterval,
    deviceConfigController.WaterPumpIntervalLenght =  waterPumpIntervalLenght,
    
    deviceConfigController.RelayEnabled =  relayEnabled,
    deviceConfigController.Relay1 =  relay1,
    deviceConfigController.Relay2 =  relay2,
    deviceConfigController.Relay3 =  relay3,
    deviceConfigController.Relay4 =  relay4,
    deviceConfigController.Relay5 =  relay5,
    deviceConfigController.Relay6 =  relay6,
    deviceConfigController.Relay7 =  relay7,
    deviceConfigController.Relay8 =  relay8

WHERE 
	deviceConfigController.IDDeviceConfigController = idDeviceConfigController;
    

UPDATE device SET ConfigVersion = ConfigVersion + 1 WHERE device.IDDevice=idDevice;
END ;;
