CREATE DEFINER=`agrumy`@`%` PROCEDURE `DeviceGet`(
	tenantID int,
	idDevice int,
	apiID varchar(128),
    macAddress varchar(18)
)
BEGIN
IF (idDevice IS NOT NULL) THEN
	BEGIN
		SELECT * FROM device where device.TenantID=tenantID and device.IDDevice=idDevice Limit 1;
	END;
END IF;

IF (idDevice IS NULL AND apiID IS NOT NULL AND macAddress IS NULL) THEN
	BEGIN
		SELECT * FROM device where device.TenantID=tenantID and  device.ApiID=apiID Limit 1;
    END;
END IF;

IF (idDevice IS NULL AND apiID IS NULL AND macAddress IS NOT NULL) THEN
	BEGIN
		SELECT * FROM device where device.TenantID=tenantID and  device.MacAddress=macAddress Limit 1;
    END;
END IF;

END ;;
DELIMITER ;
