CREATE DEFINER=`agrumy`@`%` PROCEDURE `SensorDataGet`(
    tenantID int,
	deviceID int,
    timeRange int,
    timeMDMY int,
    buildReport bool
)
BEGIN
	DECLARE sensorDataResult LONGTEXT;
	CALL `SensorDataReportBuilder`(tenantID, deviceID, timeRange, timeMDMY, sensorDataResult);
    
    IF sensorDataResult IS NOT NULL AND buildReport > 0 THEN
		INSERT INTO sensorDataReport (deviceID,ReportName,sensorData)
		VALUES(deviceID,CURRENT_TIMESTAMP(0),sensorDataResult);
    END IF;
    SELECT sensorDataResult;
END ;;
DELIMITER ;
