CREATE DEFINER=`agrumy`@`%` PROCEDURE `SensorDataGetJson`(
	deviceID int,
    tenantID int,
    timeRange int,
    timeMDMY int
)
BEGIN

SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
START TRANSACTION;


CASE timeMDMY
	WHEN 0 THEN
		SELECT JSON_ARRAYAGG(JSON_OBJECT(
			"battery", Battery,
			"temperature", Temperature,
			"soilTemperature", SoilTemperature,
			"humidity", Humidity,
			"moisture", Moisture,
			"light", Light,
			"co2", Co2,
			"tvoc", Tvoc,
			"barometer", Barometer,
			"liquidPH", LiquidPH,
			"rainLevel", RainLevel,
			"waterLevel", WaterLevel,
			"wind", Wind,
            "dateCreated",DateCreated
        )) as sensorData
        FROM sensorData
		where DateCreated > CURRENT_TIMESTAMP - INTERVAL timeRange MINUTE AND sensorData.DeviceID = deviceID and sensorData.TenantID = tenantID;
        
	WHEN 1 THEN
		SELECT JSON_ARRAYAGG(JSON_OBJECT(
			"battery", Battery,
			"temperature", Temperature,
			"soilTemperature", SoilTemperature,
			"humidity", Humidity,
			"moisture", Moisture,
			"light", Light,
			"co2", Co2,
			"tvoc", Tvoc,
			"barometer", Barometer,
			"liquidPH", LiquidPH,
			"rainLevel", RainLevel,
			"waterLevel", WaterLevel,
			"wind", Wind,
            "dateCreated",DateCreated
        )) as sensorData
        FROM sensorData
        where DateCreated > CURRENT_TIMESTAMP - INTERVAL timeRange DAY AND sensorData.DeviceID = deviceID and sensorData.TenantID = tenantID;
	WHEN 2 THEN
		SELECT JSON_ARRAYAGG(JSON_OBJECT(
			"battery", Battery,
			"temperature", Temperature,
			"soilTemperature", SoilTemperature,
			"humidity", Humidity,
			"moisture", Moisture,
			"light", Light,
			"co2", Co2,
			"tvoc", Tvoc,
			"barometer", Barometer,
			"liquidPH", LiquidPH,
			"rainLevel", RainLevel,
			"waterLevel", WaterLevel,
			"wind", Wind,
            "dateCreated",DateCreated
        )) as sensorData
        FROM sensorData
        where DateCreated > CURRENT_TIMESTAMP - INTERVAL timeRange MONTH AND sensorData.DeviceID = deviceID and sensorData.TenantID = tenantID;
	WHEN 3 THEN
		SELECT JSON_ARRAYAGG(JSON_OBJECT(
			"battery", Battery,
			"temperature", Temperature,
			"soilTemperature", SoilTemperature,
			"humidity", Humidity,
			"moisture", Moisture,
			"light", Light,
			"co2", Co2,
			"tvoc", Tvoc,
			"barometer", Barometer,
			"liquidPH", LiquidPH,
			"rainLevel", RainLevel,
			"waterLevel", WaterLevel,
			"wind", Wind,
            "dateCreated",DateCreated
        )) as sensorData
        FROM sensorData
        where DateCreated > CURRENT_TIMESTAMP - INTERVAL timeRange YEAR AND sensorData.DeviceID = deviceID and sensorData.TenantID = tenantID;
        ELSE
        select null as sensorData  from sensorData LIMIT 0;
END CASE;
COMMIT;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
