CREATE DEFINER=`agrumy`@`%` PROCEDURE `SensorDataPush`(
	jsonData LONGTEXT
)
BEGIN




INSERT 
	INTO sensorData (
	deviceID,
	tenantID,
	deviceUnitID,
    deviceUnitZoneID,
    battery,
    temperature,
    soilTemperature,
    humidity,
    moisture,
    light,
    co2,
    tvoc,
    barometer,
    liquidPH,
    rainlevel,
    waterLevel,
    wind,
    dateCreated
)
  SELECT 
	j.deviceID,
	j.tenantID,
    j.deviceUnitID,
    j.deviceUnitZoneID,
    j.battery,
    j.temperature,
    j.soilTemperature,
    j.humidity,
    j.moisture,
    j.light,
    j.co2,
    j.tvoc,
    j.barometer,
    j.liquidPH,
    j.rainlevel,
    j.waterLevel,
    j.wind,
    j.dateCreated
  FROM JSON_TABLE(
    jsonData, '$[*]' COLUMNS(
	  deviceID INT PATH '$.deviceID',
	  tenantID INT PATH '$.tenantID',
	  deviceUnitID INT PATH '$.deviceUnitID',
	  deviceUnitZoneID INT PATH '$.deviceUnitZoneID',
      battery TINYINT PATH '$.battery',
      temperature DOUBLE PATH '$.temperature',
      soilTemperature DOUBLE PATH '$.soilTemperature',
      humidity DOUBLE PATH '$.humidity',
      moisture INT PATH '$.moisture',
      light TINYINT PATH '$.light',
      co2 INT PATH '$.co2',
      tvoc INT PATH '$.tvoc',
      barometer DOUBLE PATH '$.barometer',
      liquidPH DOUBLE PATH '$.liquidPH',
      rainlevel INT PATH '$.rainLevel',
      waterLevel TINYINT PATH '$.waterLevel',
      wind SMALLINT PATH '$.wind',
      dateCreated DATETIME PATH '$.dateCreated'
    )
  ) AS j;
  
  
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `SensorDataReportBuilder` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_general_ci */ ;
