CREATE DEFINER=`agrumy`@`%` PROCEDURE `_JsonExample`(
	
)
BEGIN
DECLARE jsonData text ;
SET jsonData = '[{"deviceID":1,"tenantID":1,"battery":100,"temperature":25,"soilTemperature":25,"humidity":80,"moisture":50,"light":95,"co2":400,"tvoc":72,"barometer":null,"liquidPH":null,"waterLevel":100}]';


  SELECT 
	j.deviceID,
	j.tenantID,
    j.battery,
    j.temperature,
    j.soilTemperature,
    j.humidity,
    j.moisture,
    j.light,
    j.co2,
    j.tvoc,
    j.barometer,
    j.liquidPH,
    j.waterLevel
  FROM JSON_TABLE(
    jsonData, '$[*]' COLUMNS(
      deviceID INT PATH '$.deviceID',
      tenantID INT PATH '$.tenantID',
      battery INT PATH '$.battery',
      temperature DOUBLE PATH '$.temperature',
      soilTemperature DOUBLE PATH '$.soilTemperature',
      humidity INT PATH '$.humidity',
      moisture INT PATH '$.moisture',
      light INT PATH '$.light',
      co2 INT PATH '$.co2',
      tvoc INT PATH '$.tvoc',
      barometer DOUBLE PATH '$.barometer',
      liquidPH DOUBLE PATH '$.liquidPH',
      waterLevel INT PATH '$.waterLevel'
    )
  ) AS j;
END ;;
DELIMITER ;
