CREATE DEFINER=`agrumy`@`%` PROCEDURE `_sensorDataTest`(
	deviceID int,
    tenantID int,
    timeRange int,
    timeMDMY int
)
BEGIN
DECLARE sensorDataResult longtext;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED; 
START TRANSACTION;


SELECT JSON_ARRAYAGG(JSON_OBJECT(
			"battery", Battery,
			"temperature", Temperature,
			"soilTemperature", SoilTemperature,
			"humidity", Humidity,
			"moisture", Moisture,
			"light", Light,
			"co2", Co2,
			"tvoc", Tvoc,
			"barometer", Barometer,
			"liquidPH", LiquidPH,
			"rainLevel", RainLevel,
			"waterLevel", WaterLevel,
			"wind", Wind,
            "dateCreated",DateCreated
        )) as sensorData
		INTO sensorDataResult
        FROM sensorData;
SELECT sensorDataResult;
COMMIT;
END ;;
